        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Imagination is not an empirical or superadded power of consciousness, it is the whole of consciousness as it realizes its freedom.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "What then did you expect when you unbound the gag that muted those black mouths? That they would chant your praises? Did you think that when those heads that our fathers had forcibly bowed down to the ground were raised again, you would find adoration in their eyes?", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Every age has its own poetry; in every age the circumstances of history choose a nation, a race, a class to take up the torch by creating situations that can be expressed or transcended only through poetry.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Fascism is not defined by the number of its victims, but by the way it kills them.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Our responsibility is much greater than we might have supposed, because it involves all mankind.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "To choose this or that is to affirm at the same time the value of what we choose, because we can never choose evil. We always choose the good, and nothing can be good for us without being good for all.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "A writer who takes political, social or literary positions must act only with the means that are his. These means are the written words.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "She believed in nothing; only her skepticism kept her from being an atheist.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I hate victims who respect their executioners.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I construct my memories with my present. I am lost, abandoned in the present. I try in vain to rejoin the past: I cannot escape.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The real nature of the present revealed itself: it was what exists, all that was not present did not exist.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The past is the luxury of proprietors.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "For an occurrence to become an adventure, it is necessary and sufficient for one to recount it.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Absurd, irreducible; nothing — not even a profound and secret delirium of nature — could explain it. Obviously I did not know everything, I had not seen the seeds sprout, or the tree grow. But faced with this great wrinkled paw, neither ignorance nor knowledge was important: the world of explanations and reasons is not the world of existence. A circle is not absurd, it is clearly explained by the rotation of a straight segment around one of its extremities. But neither does a circle exist. This root, on the other hand, existed in such a way that I could not explain it.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I know I'll never jump again.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Every existing thing is born without reason, prolongs itself out of weakness and dies by chance.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Nothingness haunts being.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Generosity is nothing else than a craze to possess. All which I abandon, all which I give, I enjoy in a higher manner through the fact that I give it away.... To give is to enjoy possessively the object which one gives.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am responsible for everything ... except for my very responsibility, for I am not the foundation of my being. Therefore everything takes place as if I were compelled to be responsible. I am abandoned in the world ... in the sense that I find myself suddenly alone and without help, engaged in a world for which I bear the whole responsibility without being able, whatever I do, to tear myself away from this responsibility for an instant.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Existence precedes and rules essence.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am condemned to be free.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Man is a useless passion.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "All human activities are equivalent ... and ... all are on principle doomed to failure.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Man is condemned to be free; because once thrown into the world, he is responsible for everything he does.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "It is certain that we cannot escape anguish, for we are anguish.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The For-itself, in fact, is nothing but the pure nihilation of the In-itself; it is like a hole of being at the heart of Being.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Man is always separated from what he is by all the breadth of the being which he is not. He makes himself known to himself from the other side of the world and he looks from the horizon toward himself to recover his inner being.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Generally speaking there is no irreducible taste or inclination. They all represent a certain appropriative choice of being. It is up to existential psychoanalysis to compare and classify them. Ontology abandons us here; it has merely enabled us to determine the ultimate ends of human reality, its fundamental possibilities, and the value which haunts it.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Some men are born committed to action: they do not have a choice, they have been thrown on a path, at the end of that path, an act awaits them, their act.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "They are in bad faith — they are afraid — and fear, bad faith have an aroma that the gods find delicious. Yes, the gods like that, the pitiful souls.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Do not judge the gods, young man, they have painful secrets.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Yes, I am so free. And what a superb absence is my soul.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "A man who is free is like a mangy sheep in a herd. He will contaminate my entire kingdom and ruin my work.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "What do I care about Jupiter? Justice is a human issue, and I do not need a god to teach it to me.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "All-powerful god, who am I but the fear that I inspire in others?", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Blood doubly unites us, for we share the same blood and we have spilled blood.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Suppose that I wish to deserve the title of \"robber of remorse\" and that I place in myself all [the townspeople's] repentence?", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "It is for the sake of order that I seduced Clytemnestra, for the sake of order that I killed my king. I wanted for order to rule and that it rule through me. I have lived without desire, without love, without hope: I made order. Oh! terrible and divine passion!", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Understand me: I wish to be a man from somewhere, a man among men. You see, a slave, when he passes by, weary and surly, carrying a heavy load, limping along and looking down at his feet, only at his feet to avoid falling down; he is in his town, like a leaf in greenery, like a tree in a forest, argos surrounds him, heavy and warm, full of herself; I want to be that slave, Electra, I want to pull the city around me and to roll myself up in it like a blanket. I will not leave.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "He is dead, and my hatred has died with him.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I gave you the liberty to serve me. That is possible, but it has turned against you and there is nothing either one of us can do about it.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I came to claim my kingdom and you refused me because I was not one of you. Now I am one of you, my subjects, we are bound by blood, and I deserve to be your king. Your sins and your remorse, your mighty anguish, I take all upon myself. Fear your dead no more, they are my dead.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Your entire universe will not be enough to make me guilty. You are the king of the Gods, Jupiter, the king of the stones and of the stars, the king of the waves of the sea. But you are not the king of men.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am not your king, impudent larva? Who then has created you? You. But you should not have created me free.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am a man, Jupiter, and each man must invent his own path.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "In a world, man must create his own essence: it is in throwing himself into the world, suffering there, struggling there, that he gradually defines himself.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Man cannot will unless he has first understood that he must count on no one but himself; that he is alone, abandoned on earth in the midst of his infinite responsibilities, without help, with no other aim than the one he sets himself, with no other destiny than the one he forges for himself on this earth.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "With despair, true optimism begins: the optimism of the man who expects nothing, who knows he has no rights and nothing coming to him, who rejoices in counting on himself alone and in acting alone for the good of all.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "man first of all exists, encounters himself, surges up in the world – and defines himself afterwards.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Everything is indeed permitted if God does not exist, and man is in consequence forlorn, for he cannot find anything to depend upon either within or outside himself. He discovers forthwith, that he is without excuse.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Quietism is the attitude of people who say, \"let others do what I cannot do.\" The doctrine I am presenting before you is precisely the opposite of this, since it declares that there is no reality except in action. It goes further, indeed, and adds, \"Man is nothing else but what he purposes, he exists only in so far as he realizes himself, he is therefore nothing else but the sum of his actions, nothing else but what his life is.\" Hence we can well understand why some people are horrified by our teaching.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "We will freedom for freedom's sake, in and through particular circumstances. And in thus willing freedom, we discover that it depends entirely upon the freedom of others and that the freedom of others depends upon our own. Obviously, freedom as the definition of a man does not depend upon others, but as soon as there is a commitment, I am obliged to will the liberty of others at the same time as my own. I cannot make liberty my aim unless I make that of others equally my aim.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Existentialism is nothing else but an attempt to draw the full conclusions from a consistently atheistic position. Its intention is not in the least that of plunging men into despair. And if by despair one means as the Christians do – any attitude of unbelief, the despair of the existentialists is something different. Existentialism is not atheist in the sense that it would exhaust itself in demonstrations of the non-existence of God. It declares, rather, that even if God existed that would make no difference from its point of view. Not that we believe God does exist, but we think that the real problem is not that of His existence; what man needs is to find himself again and to understand that nothing can save him from himself, not even a valid proof of the existence of God. In this sense existentialism is optimistic. It is a doctrine of action, and it is only by self-deception, by confining their own despair with ours that Christians can describe us as without hope.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Life has no meaning a priori … It is up to you to give it a meaning, and value is nothing but the meaning that you choose.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "It is the good children, Madame, who make the most terrible revolutionaries. They say nothing, they do not hide under the table, they eat only one sweet at a time, but later on, they make Society pay dearly for it!", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I respect orders but I respect myself too and I do not obey foolish rules made especially to humiliate me.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "It is the same thing: killing, dying, it is the same thing: one is just as alone in each. He is lucky, he will only die once. As for me, for ten days I have been killing him at every minute.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I say a murder is abstract. You pull the trigger and after that you do not understand anything that happens.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Politics is a science. You can demonstrate that you are right and that others are wrong.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I do not give a damn about the dead. They died for the [Communist] Party and the Party can decide what it wants. I practice a live man's politics, for the living.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "What do you want to do with the [Communist] Party? A racing stable? What good is it to sharpen a knife every day if you never use it for slicing? A party is never more than a means. There is only one objective: power.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Intellectuals cannot be good revolutionaries; they are just good enough to be assassins.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I was not the one to invent lies: they were created in a society divided by class and each of us inherited lies when we were born. It is not by refusing to lie that we will abolish lies: it is by eradicating class by any means necessary.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "As far as men go, it is not what they are that interests me, but what they can become.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "You take souls for vegetables.... The gardener can decide what will become of his carrots but no one can choose the good of others for them.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The best work is not what is most difficult for you; it is what you do best.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "If you are not already dead, forgive. Rancor is heavy, it is worldly; leave it on earth: die light.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I know only one Church: it is the society of men.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "If a victory is told in detail, one can no longer distinguish it from a defeat.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "It is too early to love. We will buy the right to do so by shedding blood.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "When the rich make war, it's the poor that die.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "You see, I divide men into three categories: those who have a lot of money, those who have none at all and those who have a little. The first want to keep what they have: their interest is to maintain order; the second want to take what they do not have: their interest is to destroy the existing order and to establish one which is profitable to them. They each are realist, people with whom one can agree. The third group want to overthrow the social order to take what they do not have, while still preserving it so that no one takes away what they have. Thus, they preserve in fact what they destroy in theory, or they destroy in fact what they seem to preserve. Those are the idealists.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Why commit Evil? Because Good has already been done. Who has done it? God the Father. I, on the other hand, am improvising.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am not virtuous. Our sons will be if we shed enough blood to give them the right to be.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "If you want to deserve Hell, you need only stay in bed. The world is iniquity; if you accept it, you are an accomplice, if you change it you are an executioner.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "There are two types of poor people, those who are poor together and those who are poor alone. The first are the true poor, the others are rich people out of luck.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I will not be modest. Humble, as much as you like, but not modest. Modesty is the virtue of the lukewarm.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "One cannot become a saint when one works sixteen hours a day.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "We will not go to Heaven,Goetz, and even if we both entered it, we would not have eyes to see each other, nor hands to touch each other. Up there, God gets all the attention.... We can only love on this earth and against God.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "So that is what hell is. I would never have believed it. You remember: the fire and brimstone, the torture. Ah! the farce. There is no need for torture: Hell is other people.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "One always dies too soon — or too late. And yet, life is there, finished: the line is drawn, and it must all be added up. You are nothing other than your life.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I think of death only with tranquility, as an end. I refuse to let death hamper life. Death must enter life only to define it.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "A man is what he wills himself to be.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The anti‐Semite has chosen hate because hate is a faith; at the outset he has chosen to devaluate words and reasons. How entirely at ease he feels as a result. How futile and frivolous discussions about the rights of the Jew appear to him. He has placed himself on other ground from the beginning. If out of courtesy he consents for a moment to defend his point of view, he lends himself but does not give himself. He tries simply to project his intuitive certainty onto the plane of discourse.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "The anti‐Semite understands nothing about modern society. He would be incapable of conceiving of a constructive plan; his action cannot reach the level of the methodical; it remains on the ground of passion. To a long‐term enterprise he prefers an explosion of rage analogous to the running amuck of the Malays. His intellectual activity is confined to ''interpretation''; he seeks in historical events the signs of the presence of an evil power. Out of this spring those childish and elaborate fabrications which give him his resemblance to the extreme paranoiacs.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "If the Jew did not exist, the anti-Semite would invent him.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "What do we mean by saying that existence precedes essence? We mean that man first of all exists, encounters himself, surges up in the world—and defines himself afterwards. If man as the existentialist see him is not definable, it is because to begin with he is nothing. He will not be anything until later, and then he will be what he makes of himself. Thus, there is no human nature, because there is no God to have a conception of it. Man simply is. Not that he is simply what he conceives himself to be, but he is what he wills, and as he conceives himself after already existing – as he wills to be after that leap towards existence. Man is nothing else but that which he makes of himself. That is the first principle of existentialism.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "First, what do we mean by anguish? The existentialist frankly states that man is in anguish. His meaning is as follows-When a man commits himself to anything, fully realizing that he is not only choosing what he will be, but is thereby at the same time a legislator deciding for the whole of mankind-in such a moment a man cannot escape from the sense of complete and profound responsibility.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "And when we speak of \"abandonment\" - a favorite word of Heidegger - we only mean to say that God does not exist and that it is necessary to draw the consequences of his absence to the end.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Dostoevsky once wrote: \"If God did not exist, everything would be permitted\"; and that, for existentialism, is the starting point. Everything is indeed permitted if God does not exist, and man is in consequence forlorn, for he cannot find anything to depend upon either within or outside himself.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "When Descartes said, \"Conquer yourself rather than the world,\" what he meant was, at bottom, - the same - that we should act without hope. Marxists, to whom I have said thus have answered: \"Your action is limited, obviously, by your death: but you can rely upon the help of others.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Our aim is precisely to establish the human kingdom as a pattern of values in distinction from the material world. But the subjectivity which we thus postulate as the standard of truth is no narrowly individual subjectivism, for as we have demonstrated, it is not only one's own self that one discovers in the cogito, but those of others too. Contrary to the philosophy of Descartes, contrary to that of Kant, when we say \"I think\" we are attaining to ourselves in the presence of the other, and we are just as certain of the other as we are of ourselves. Thus the man who discovers himself directly in the cogito also discovers all the others, and discovers them as the condition of his own existence. He realizes that he can't be anything unless others recognize him as such. I cannot obtain any truth whatsoever about myself, except through the mediation of another. The other is indispensable to my existence, and equally so to any knowledge I can have of myself.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "A man who belongs to some communist or revolutionary society wills certain concrete ends, which imply the will to freedom, and that freedom is willed in community. We will freedom for freedom's sake, and in and through the particular circumstances. And in thus willing freedom, we discover that it depends entirely upon the freedom of others and that the freedom of others depends upon our own.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "We will freedom for freedom's sake, in and through particular circumstances. And in thus willing freedom, we discover that it depends entirely upon the freedom of others and that the freedom of others depends upon our own. Obviously, freedom as the definition of a man does not depend upon others, but as soon as there is a commitment, I am obliged to will the liberty of others at the same time as my own. I cannot make liberty my aim unless I make that of others equally my aim.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "We are in hell, and there's never any mistake there. People are not damned for nothing.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "I am mean: that means that I need the suffering of others to exist. A flame. A flame in their hearts. When I am all alone, I am extinguished.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "You have stolen my face from me: you know it and I no longer do.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Don't you feel the same way? When I cannot see myself, even though I touch myself, I wonder if I really exist.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Ha! to forget. How childish! I feel you in my bones. Your silence screams in my ears. You may nail your mouth shut, you may cut out your tongue, can you keep yourself from existing? Will you stop your thoughts.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "We are in hell and I will have my turn!", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "If only you knew how little I care. Cowardly or not, as long as he is a good kisser.", Author = "Jean-Paul Sartre" },
        };
    }
}